#!/usr/bin/env python3
"""Export only the selected scout hall's seat geometry and reviewed raster bounds."""
import argparse
import collections
import hashlib
import json
import pathlib

parser=argparse.ArgumentParser(description=__doc__)
parser.add_argument('snapshot',type=pathlib.Path)
args=parser.parse_args()
root=pathlib.Path(__file__).resolve().parents[1]
source=next(s for s in json.loads(args.snapshot.read_text())['sources'] if s['occasion']['title']=='Skautský ples 2026')
b=source['blueprints'][0]
assert b['configuration']['dimensions']=={'width':32,'height':32}
# Intentionally excludes source identities, products, states and reservations.
seats=sorted([[s['group'],s['title'],s['x'],s['y']] for s in b['objects']],key=lambda s:(s[0],s[1]))
assert len(seats)==182
assert collections.Counter(s[0] for s in seats)=={i:4 if i in (18,19) else 6 for i in range(1,32)}
geometry=json.loads((root/'tool/fixtures/scout_hall_geometry.json').read_text())
rectangles=geometry['rectangles']
tables=sorted([[int(r['name']),*r['rect']] for r in rectangles if r['name'].isdigit()])
architecture=[[r['name'],*r['rect']] for r in rectangles if not r['name'].isdigit()]
assert [t[0] for t in tables]==list(range(1,32))
data={'tables':tables,'architecture':architecture,'seats':seats}
digest=hashlib.sha256(json.dumps(data,sort_keys=True).encode()).hexdigest()
lines=['// Generated by tool/import_scout_reference.py; structural geometry only.',
       '// Reviewed original raster bounds, plus every original seat coordinate.',
       f"const scoutReferenceDigest = '{digest}';",
       f"const scoutReferenceRasterDigest = '{geometry['sourceRasterSha256']}';"]
for name,rows in data.items():
 record_type = '(int, String, int, int)' if name == 'seats' else '(int, double, double, double, double)' if name == 'tables' else '(String, double, double, double, double)'
 lines.append(f'const scout{name.title()} = <{record_type}>[')
 for row in rows:
  values=[json.dumps(v,ensure_ascii=False) if isinstance(v,str) else str(round(v,6)) if isinstance(v,float) else str(v) for v in row]
  lines.append('  ('+', '.join(values)+'),')
 lines.append('];')
(root/'lib/src/templates/scout_reference_data.dart').write_text('\n'.join(lines)+'\n')
print(f'Extracted 31 tables, 182 seats, {len(architecture)} architectural footprints; SHA256 {digest}')
